 // Each piece lies flat on the track: its own x follows the rail, its z is the horizontal side, its y the normal (never rolled on the slopes).
 const orient=dir=>{side.crossVectors(UP,dir).normalize();up.crossVectors(dir,side).normalize();M.makeBasis(dir,up,side);Q.setFromRotationMatrix(M);};
